def transform(grid):
    h, w = len(grid), len(grid[0])
    offsets = {}
    for r, row in enumerate(grid):
        for c, v in enumerate(row):
            if v:
                d = c-r
                if d in offsets and offsets[d] != v:
                    raise ValueError('inconsistent diagonal')
                offsets[d] = v
    # Detect periodic diagonal coloring, selecting the shortest period consistent
    # with all marked diagonal offsets, then repeat over the output grid.
    for p in range(1, h+w+1):
        vals = {}
        ok = True
        for d, v in offsets.items():
            k = d % p
            if k in vals and vals[k] != v:
                ok = False
                break
            vals[k] = v
        if ok and len(vals) == p:
            return [[vals[(c-r) % p] for c in range(w)] for r in range(h)]
    # fallback shortest color repeating period fully assigned
    p = max(offsets) - min(offsets) + 1
    vals = {d % p:v for d,v in offsets.items()}
    return [[vals.get((c-r)%p,0) for c in range(w)] for r in range(h)]
